function normalizeAnswer(v){return String(v).toLowerCase().replace(/ё/g,'е').replace(/[₀₁₂₃₄₅₆₇₈₉]/g,c=>'₀₁₂₃₄₅₆₇₈₉'.indexOf(c)).replace(/²/g,'2').replace(/³/g,'3').replace(/[^a-zа-я0-9/=.,]/g,'').replace(/,/g,'.').replace(/[.,]+$/,'');}
function checkAnswer(question,text){const expected=[question.options[question.correct],...(question.aliases||[])];return expected.some(a=>normalizeAnswer(a)===normalizeAnswer(text));}

function createGame(db, questions, topics, { now = Date.now } = {}) {
 db.exec('CREATE TABLE IF NOT EXISTS rooms (code TEXT PRIMARY KEY, data TEXT NOT NULL, updated INTEGER NOT NULL)');
 const get=db.prepare('SELECT data FROM rooms WHERE code = ?');
 const save=db.prepare('INSERT OR REPLACE INTO rooms(code,data,updated) VALUES(?,?,?)');
 const cleanup=db.prepare('DELETE FROM rooms WHERE updated < ?');
 const fail=(message,status=400)=>{const e=new Error(message);e.status=status;throw e};
 const shuffle=arr=>{const a=[...arr];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a};
 const name=v=>{if(typeof v!=='string'||!v.trim()||v.trim().length>20)fail('Имя должно содержать от 1 до 20 символов');return v.trim()};
 const defaults={rounds:12,seconds:30,teamCount:2,topics:Object.keys(topics)};
 function settings(v){if(!v||![6,12,18,24].includes(v.rounds)||![20,30,45].includes(v.seconds)||![2,3,4].includes(v.teamCount)||!Array.isArray(v.topics)||!v.topics.length||v.topics.some(t=>!topics[t]))fail('Проверьте настройки игры');return {...v,topics:[...new Set(v.topics)]};}
 function begin(r){r.index++;if(r.index>=r.deck.length){r.phase='finished';return}r.phase='question';r.answers={};r.winner=null;r.deadline=now()+r.settings.seconds*1000;r.roundId=crypto.randomUUID();}
 function reveal(r){r.phase='reveal';r.nextAt=now()+6500;const q=r.deck[r.index];for(const [team,a]of Object.entries(r.answers)){a.points=a.correct?100:0;r.scores[team]+=a.points;}}
 function tick(r){if(r.phase==='question'&&now()>=r.deadline)reveal(r);if(r.phase==='reveal'&&now()>=r.nextAt)begin(r);if(r.players.length&&!r.players.some(p=>p.id===r.host&&now()-p.seen<90000)){const online=r.players.find(p=>now()-p.seen<90000);if(online)r.host=online.id;}}
 function publicState(r,p){const q=r.deck?.[r.index];return {code:r.code,host:r.host,me:p.id,serverTime:now(),phase:r.phase,players:r.players.map(({id,name,team,seen})=>({id,name,team,online:now()-seen<15000})),teams:r.teams.slice(0,r.settings.teamCount),activeTeams:r.activeTeams||[],settings:r.settings,scores:r.scores,round:r.index+1,total:r.deck?.length||r.settings.rounds,roundId:r.roundId,deadline:r.deadline,nextAt:r.nextAt,winner:r.winner,question:q?{topic:q.topic,text:q.text,...(r.phase!=='question'?{answer:q.options[q.correct]}:{})}:null,answers:Object.fromEntries(Object.entries(r.answers||{}).map(([t,a])=>[t,r.phase==='question'?{submitted:true,by:a.by}:a]))};}
 function write(r,p){save.run(r.code,JSON.stringify(r),now());return publicState(r,p);}
 return function handle(action,b={},token=''){
 cleanup.run(now()-24*3600000);
 if(action==='create'){
  if(db.prepare('SELECT COUNT(*) AS n FROM rooms').get().n>=1000)fail('Сервер заполнен. Попробуйте позже.',503);
  const p={id:crypto.randomUUID(),token:crypto.randomUUID(),name:name(b.name),team:null,seen:now()};
  let code;do{code=Array.from(crypto.getRandomValues(new Uint8Array(6)),n=>'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'[n%32]).join('')}while(get.get(code));
  const r={code,host:p.id,players:[p],settings:defaults,teams:['Молнии','Кометы','Лисы','Совы'],scores:[0,0,0,0],phase:'lobby',index:-1,answers:{}};
  return {token:p.token,state:write(r,p)};
 }
 const code=String(b.code||'').trim().toUpperCase();const row=get.get(code);if(!row)fail('Комната не найдена. Проверьте код или создайте новую.',404);const r=JSON.parse(row.data);
 if(action==='join'){
  if(r.phase!=='lobby')fail('Игра уже идёт. Дождитесь новой партии.');if(r.players.length>=32)fail('В комнате уже 32 игрока');
  const p={id:crypto.randomUUID(),token:crypto.randomUUID(),name:name(b.name),team:null,seen:now()};r.players.push(p);return {token:p.token,state:write(r,p)};
 }
 const p=r.players.find(p=>p.token===token);if(!p)fail('Войдите в комнату заново.',401);p.seen=now();tick(r);
 const host=()=>{if(p.id!==r.host)fail('Это действие доступно только ведущему.',403)};
 const lobby=()=>{if(r.phase!=='lobby')fail('Изменения доступны до начала игры.')};
 if(action==='team'){lobby();if(!Number.isInteger(b.team)||b.team<0||b.team>=r.settings.teamCount)fail('Выберите существующую команду');p.team=b.team;}
 else if(action==='configure'){host();lobby();r.settings=settings(b.settings);for(const x of r.players)if(x.team>=r.settings.teamCount)x.team=null;}
 else if(action==='rename'){host();lobby();if(!Number.isInteger(b.team)||b.team<0||b.team>=r.settings.teamCount)fail('Команда не найдена');r.teams[b.team]=name(b.name);}
 else if(action==='start'){
  host();lobby();const online=r.players.filter(p=>now()-p.seen<90000);if(online.some(p=>p.team===null))fail('Все игроки должны выбрать команду');if(new Set(online.map(p=>p.team)).size<2)fail('Нужны игроки хотя бы в двух командах');
  const pools=r.settings.topics.map(t=>shuffle(questions.filter(q=>q.topic===t)));const deck=[];while(deck.length<r.settings.rounds&&pools.some(a=>a.length)){for(const pool of shuffle(pools)){if(pool.length&&deck.length<r.settings.rounds){const q=pool.pop();const order=shuffle([0,1,2,3]);deck.push({...q,options:order.map(i=>q.options[i]),correct:order.indexOf(q.correct)})}}}
  r.deck=deck;r.scores=[0,0,0,0];r.index=-1;r.activeTeams=[...new Set(online.map(p=>p.team))];begin(r);
 }
 else if(action==='answer'){
  if(r.phase!=='question'||b.roundId!==r.roundId)fail('Этот вопрос уже закрыт.');if(p.team===null||!r.activeTeams.includes(p.team))fail('Вы не участвуете в раунде');if(r.answers[p.team])fail('Ваша команда уже ответила.');if(typeof b.text!=='string'||!b.text.trim()||b.text.trim().length>100)fail('Напишите ответ: от 1 до 100 символов');
  const correct=checkAnswer(r.deck[r.index],b.text);r.answers[p.team]={text:b.text.trim(),by:p.name,correct,points:0};if(correct){r.winner=p.team;reveal(r)}else if(r.activeTeams.every(t=>r.answers[t]))reveal(r);
 }
 else if(action==='next'){host();if(r.phase!=='reveal'||b.roundId!==r.roundId)fail('Дождитесь итогов вопроса');begin(r);}
 else if(action==='replay'){host();if(r.phase!=='finished')fail('Сначала закончите партию');r.phase='lobby';r.deck=null;r.index=-1;r.answers={};r.scores=[0,0,0,0];}
 else if(action==='leave'){r.players=r.players.filter(x=>x.id!==p.id);if(p.id===r.host)r.host=r.players[0]?.id;if(!r.players.length){db.prepare('DELETE FROM rooms WHERE code = ?').run(code);return {left:true}}save.run(code,JSON.stringify(r),now());return {left:true};}
 else if(action!=='state')fail('Неизвестное действие',404);
 return {state:write(r,p)};
 };
}

function createTransport(game, assets, publicOrigin) {
 const rates=new Map();
 return async function handle(request,ip='unknown') {
  const url=new URL(request.url), origin=request.headers.get('origin');
  const allowed=!origin||origin===url.origin||origin==='https://kittler777.github.io'||origin===publicOrigin;
  const headers={'Content-Type':'application/json; charset=utf-8','Cache-Control':'no-store','X-Content-Type-Options':'nosniff','Referrer-Policy':'no-referrer',...(allowed&&origin?{'Access-Control-Allow-Origin':origin,'Vary':'Origin'}:{})};
  if(request.method==='OPTIONS')return new Response(null,{status:allowed?204:403,headers:{...headers,'Access-Control-Allow-Headers':'Content-Type, Authorization','Access-Control-Allow-Methods':'POST, OPTIONS','Access-Control-Max-Age':'600'}});
  if(url.pathname==='/health')return Response.json({ok:true,game:'peremena',questions:120},{headers});
  if(url.pathname.startsWith('/api/')){
   if(!allowed)return Response.json({error:'Источник запроса не разрешён'},{status:403,headers});
   if(request.method!=='POST')return Response.json({error:'Используйте POST'},{status:405,headers});
   const action=url.pathname.slice(5);
   const key=ip+':'+(action==='create'?'create':action==='join'?'join':'play');const max=action==='create'?15:action==='join'?100:5000;const windowMs=action==='create'?3600000:60000;
   const t=Date.now();let rate=rates.get(key);if(!rate||t-rate.start>windowMs){rate={start:t,n:0};rates.set(key,rate)}if(++rate.n>max)return Response.json({error:'Слишком много запросов. Попробуйте позже.'},{status:429,headers});
   if(rates.size>10000)for(const [k,r]of rates)if(t-r.start>3600000)rates.delete(k);
   try{
    if(Number(request.headers.get('content-length'))>8192)return Response.json({error:'Слишком большой запрос'},{status:413,headers});
    let body='';const reader=request.body?.getReader();if(reader){const decoder=new TextDecoder();let size=0;while(true){const {done,value}=await reader.read();if(done)break;size+=value.byteLength;if(size>8192){await reader.cancel();return Response.json({error:'Слишком большой запрос'},{status:413,headers})}body+=decoder.decode(value,{stream:true})}body+=decoder.decode()}
    let payload;try{payload=JSON.parse(body||'{}')}catch{return Response.json({error:'Некорректный JSON'},{status:400,headers})}if(!payload||typeof payload!=='object'||Array.isArray(payload))return Response.json({error:'Некорректный запрос'},{status:400,headers});
    const token=(request.headers.get('authorization')||'').replace(/^Bearer /,'');return Response.json(game(action,payload,token),{headers});
   }catch(e){if(!e.status)console.error('Game request failed:',e.message);return Response.json({error:e.status?e.message:'Ошибка сервера. Попробуйте ещё раз.'},{status:e.status||500,headers})}
  }
  const path=url.pathname.endsWith('/')?'index.html':url.pathname.split('/').pop();const file=assets[path];if(file&&request.method==='GET')return new Response(file.body,{headers:{'Content-Type':file.type,'X-Content-Type-Options':'nosniff','Cache-Control':'no-cache','Content-Security-Policy':"default-src 'self'; connect-src 'self' https://*.up.railway.app; img-src 'self' data:; script-src 'self'; style-src 'self' 'unsafe-inline'; object-src 'none'; base-uri 'self'; frame-ancestors 'none'"}});
  return new Response('Not found',{status:404});
 };
}

const assets={"index.html":{"body":"<!doctype html>\n<html lang=\"ru\">\n<head><meta charset=\"UTF-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"theme-color\" content=\"#175744\"><meta name=\"description\" content=\"Перемена: собирайте друзей в комнате по коду, выбирайте команды и соревнуйтесь в школьной викторине.\"><title>Перемена — викторина с друзьями</title><link rel=\"icon\" href=\"data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 64 64'%3E%3Crect width='64' height='64' rx='18' fill='%23175744'/%3E%3Ctext x='32' y='46' text-anchor='middle' font-family='sans-serif' font-size='48' fill='%23d5f26d'%3EП%3C/text%3E%3C/svg%3E\"><link rel=\"stylesheet\" href=\"style.css\"><script src=\"config.js\"></script><script type=\"module\" src=\"app.js\"></script></head>\n<body><header><a class=\"brand\" href=\"./\" aria-label=\"Перемена, главная\"><span class=\"brand-icon\">п.</span>перемена<span class=\"brand-dot\">✳</span></a><span class=\"header-note\">Время поиграть вместе</span><span id=\"connection\" class=\"connection\">● Онлайн-викторина</span></header><main id=\"app\"></main><div id=\"toast\" role=\"status\" aria-live=\"polite\"></div><footer><span>Знания школьные. Азарт настоящий.</span><button class=\"text-button\" data-action=\"rules\">Как играть ↗</button></footer><dialog id=\"rules\"><button class=\"dialog-close\" aria-label=\"Закрыть правила\" data-action=\"closeRules\">×</button><span class=\"eyebrow\">ВСЁ ПРОСТО</span><h2>Одна комната.<br>Общий азарт.</h2><ol><li>Создайте комнату и отправьте друзьям код или ссылку.</li><li>Каждый входит со своего телефона или компьютера и выбирает команду. Нужно минимум две команды.</li><li>Ведущий выбирает предметы, число вопросов и время, затем запускает игру.</li><li>Все команды одновременно видят один вопрос. Обсудите его, напишите ответ и нажмите «Ответить». У каждой команды одна попытка; ответ отправляет любой её участник.</li><li>Первая команда с правильным ответом получает 100 очков и завершает раунд. Неверный ответ приносит 0 очков — остальные команды могут успеть ответить.</li><li>Ответ открывается после первого правильного ответа, после попыток всех команд или по окончании таймера. Следующий вопрос появится через 7 секунд.</li></ol><p class=\"muted\">До 32 игроков и 4 команд. Если обновить страницу в той же вкладке, вы вернётесь в игру. Неактивная комната удаляется через 24 часа.</p></dialog></body></html>\n","type":"text/html; charset=utf-8"},"style.css":{"body":":root{--bg:#f6f5ee;--ink:#1c342c;--green:#175744;--lime:#d6ed82;--muted:#6c776f;--line:#dce0d6;--white:#fffefa;--team0:#d7ef8a;--team1:#cbdfff;--team2:#ffd3b4;--team3:#e7d4fa}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font-family:Arial,Helvetica,sans-serif;font-size:16px;line-height:1.5}button,input,select{font:inherit}button,a,input,select{touch-action:manipulation}button{cursor:pointer}button:disabled{cursor:default;opacity:.5}button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible{outline:3px solid #7eae49;outline-offset:4px}header,main,footer{max-width:1240px;margin:auto;padding:0 40px}header{display:flex;align-items:center;justify-content:space-between;height:112px;border-bottom:1px solid var(--line);gap:24px}.brand{color:var(--ink);font-size:29px;letter-spacing:-1.2px;text-decoration:none;font-weight:800;display:flex;align-items:center;gap:12px}.brand-icon{background:var(--green);color:var(--lime);border-radius:13px;width:43px;height:43px;display:grid;place-items:center;font-size:31px;line-height:1}.brand-dot{color:var(--green);font-size:33px}.header-note{font-size:14px;color:var(--muted)}.connection{font-size:12px;color:var(--green);padding:8px 12px;background:#e7eddf;border-radius:99px;white-space:nowrap}main{min-height:calc(100vh - 190px);padding-top:54px;padding-bottom:50px}footer{border-top:1px solid var(--line);padding-top:22px;padding-bottom:22px;display:flex;justify-content:space-between;font-size:13px;color:var(--muted)}h1,h2,h3,p{margin:0}h1{font-size:clamp(52px,6.3vw,84px);line-height:1.04;letter-spacing:-4.8px;font-weight:750;margin:22px 0}h1 em{font-style:normal;color:var(--green)}h2{font-size:32px;line-height:1.2;letter-spacing:-1.2px}h3{font-size:21px;letter-spacing:-.5px}.eyebrow{font-size:11px;letter-spacing:1.8px;font-weight:bold;display:inline-flex;align-items:center;gap:7px}.eyebrow-dot{width:8px;height:8px;border-radius:50%;background:var(--green)}.hero{display:grid;grid-template-columns:1.1fr .85fr;gap:76px;align-items:start}.lead{font-size:18px;color:var(--muted);max-width:460px;line-height:1.65}.hero-tags{display:flex;flex-wrap:wrap;gap:9px;margin-top:26px}.tag{background:#ecefe4;border:1px solid #dfe4d5;border-radius:8px;padding:6px 11px;font-size:12px}.card{background:var(--white);border:1px solid var(--line);border-radius:23px;padding:30px}.join-card{box-shadow:0 16px 40px #2b453308}.card-title{display:flex;align-items:center;justify-content:space-between;margin-bottom:8px}.small-star{font-size:33px;color:var(--green)}.muted{color:var(--muted);font-size:14px}.tabs{display:flex;padding:5px;background:#eff1e8;border-radius:12px;margin:24px 0}.tab{flex:1;border:0;background:none;padding:11px 6px;border-radius:9px;font-weight:600;font-size:14px}.tab.active{background:var(--white);box-shadow:0 2px 4px #20372c10;color:var(--green)}label.field{display:block;font-size:13px;font-weight:600;margin-bottom:18px}input,select{border:1px solid #d5ddd0;background:var(--white);border-radius:11px;padding:12px 14px;color:var(--ink);width:100%;min-width:0;margin-top:7px;line-height:1.5}input::placeholder{color:#92988e}input.code{text-transform:uppercase;letter-spacing:5px;font-weight:700;font-size:20px}.primary{background:var(--green);border:1px solid var(--green);border-radius:12px;padding:14px 21px;color:var(--white);font-weight:600;display:inline-flex;align-items:center;justify-content:center;gap:24px}.primary.full{width:100%;justify-content:space-between}.secondary{background:#eff2e8;border:1px solid #dce3d5;border-radius:11px;padding:10px 15px;color:var(--green);font-weight:600}.text-button{border:0;background:none;color:inherit;padding:0;font-size:inherit}.hint{font-size:12px;color:var(--muted);margin-top:16px;text-align:center}.sample{margin-top:32px;display:flex;gap:17px;align-items:center}.sample-symbol{height:68px;width:68px;flex-shrink:0;background:var(--lime);color:var(--green);font-size:42px;border-radius:50%;display:grid;place-items:center;transform:rotate(-12deg)}.sample strong{display:block;font-size:16px}.steps{display:grid;grid-template-columns:repeat(3,1fr);gap:20px;margin-top:56px;padding-top:30px;border-top:1px solid var(--line)}.step{display:flex;gap:14px}.step-num{color:var(--green);font-size:12px;font-weight:bold;border:1px solid #cfd8c7;border-radius:50%;height:30px;width:30px;flex-shrink:0;display:grid;place-items:center}.step strong{font-size:15px}.step p{font-size:13px;color:var(--muted);margin-top:4px}.room-top{display:flex;justify-content:space-between;align-items:center;gap:20px;margin-bottom:28px}.room-top h1{font-size:43px;letter-spacing:-2px;margin:8px 0}.room-actions{display:flex;gap:8px;align-items:center}.code-pill{background:var(--green);color:var(--lime);padding:12px 20px;border-radius:13px;font-size:21px;font-weight:bold;letter-spacing:4px;border:0}.room-layout{display:grid;grid-template-columns:minmax(0,1fr) 320px;gap:24px}.team-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:17px;margin-top:22px}.team-card{padding:22px;border:1px solid var(--line);border-radius:17px;background:var(--white)}.team-band{height:6px;background:var(--tc);border-radius:3px;margin-bottom:18px}.team-title{display:flex;justify-content:space-between;gap:8px;align-items:center}.team-title span.count{font-size:12px;color:var(--muted)}.members{display:flex;gap:6px;flex-wrap:wrap;min-height:64px;padding:16px 0}.member{font-size:12px;background:#f1f3ea;padding:6px 9px;border-radius:7px}.member.offline{opacity:.45}.team-button{width:100%;border:1px solid #d9dfd2;background:transparent;padding:10px;border-radius:10px;font-size:13px;font-weight:600}.team-button.mine{background:var(--tc);border-color:transparent}.waiting{margin-top:20px;padding:15px;background:#ecefe4;border-radius:12px;font-size:13px}.settings{display:flex;flex-direction:column;gap:18px}.settings .field{margin:0}.settings h3{margin-bottom:2px}.settings-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.topic-checks{display:flex;flex-wrap:wrap;gap:7px;margin-top:8px}.topic-checks label{font-size:12px;border:1px solid var(--line);padding:6px 9px;border-radius:8px;cursor:pointer;background:#f5f6f0;display:flex;align-items:center;gap:5px}.topic-checks input{width:13px;height:13px;padding:0;margin:0;accent-color:var(--green)}.rule-mini{font-size:12px;color:var(--muted);border-top:1px solid var(--line);padding-top:16px}.rule-mini strong{color:var(--green)}.rename{display:flex;gap:6px;margin-top:12px}.rename input{font-size:12px;padding:6px 8px;margin:0}.rename button{border:0;background:#eff2e8;border-radius:7px;color:var(--green);padding:0 10px}.game-stage{background:var(--white);border:1px solid var(--line);border-radius:23px;padding:34px}.question-top{display:flex;justify-content:space-between;align-items:center;gap:12px}.round-label{font-size:12px;color:var(--muted)}.timer{background:var(--lime);color:var(--green);font-size:19px;font-weight:bold;border-radius:50%;height:60px;width:60px;display:grid;place-items:center;font-variant-numeric:tabular-nums;flex-shrink:0}.timer.urgent{background:#ffe0cf;color:#923820}.progress{height:5px;border-radius:3px;background:#ecefe4;margin:23px 0 28px;overflow:hidden}.progress i{display:block;height:100%;background:var(--green);transition:width .2s}.question{font-size:30px;line-height:1.35;letter-spacing:-.8px;margin-top:24px;min-height:90px}.options{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin:25px 0}.option{background:#f7f8f2;border:1px solid #dee3d7;border-radius:13px;padding:17px;text-align:left;display:flex;gap:12px;align-items:center;min-height:73px;color:var(--ink)}.option .letter{height:28px;width:28px;flex-shrink:0;border:1px solid #d6ddd0;border-radius:8px;display:grid;place-items:center;font-size:12px;font-weight:700}.option.selected{border:2px solid var(--green);padding:16px;background:#eef4df}.option.correct{background:#e1efd0;border-color:#63994c;opacity:1}.option.wrong{background:#ffe4dc;border-color:#c17864;opacity:1}.answer-note{font-size:14px;color:var(--green);background:#eef3e4;border-radius:11px;padding:14px;margin-top:16px}.scoreboard{display:flex;flex-direction:column;gap:13px}.score-row{border-bottom:1px solid var(--line);padding:13px 0}.score-head{display:flex;justify-content:space-between;align-items:center}.score-head strong{font-size:25px}.team-dot{width:9px;height:9px;border-radius:50%;display:inline-block;margin-right:7px;background:var(--tc)}.score-row small{color:var(--muted);font-size:12px}.status-sub{margin-top:5px;font-size:12px;color:var(--muted)}.results{max-width:770px;margin:auto;text-align:center}.trophy{width:100px;height:100px;background:var(--lime);color:var(--green);font-size:58px;display:grid;place-items:center;border-radius:50%;margin:0 auto 22px}.results h1{font-size:55px;letter-spacing:-3px}.podium{margin:28px 0;display:flex;flex-direction:column;gap:10px}.podium-row{display:flex;justify-content:space-between;align-items:center;padding:19px 23px;background:var(--white);border:1px solid var(--line);border-radius:14px;text-align:left}.podium-row.winner{background:var(--lime);border-color:#c3d879}.podium-row strong{font-size:27px}.rank{font-size:15px;margin-right:16px;color:var(--muted)}.error-card{margin:0 0 20px;padding:15px;background:#ffe6da;border-radius:11px;color:#754132;font-size:14px}#toast{position:fixed;bottom:25px;left:50%;transform:translateX(-50%);z-index:10;background:var(--ink);color:white;padding:13px 21px;border-radius:12px;max-width:90vw;box-shadow:0 6px 25px #0002;display:none;font-size:14px}#toast.visible{display:block}dialog{border:1px solid var(--line);border-radius:24px;padding:36px;max-width:620px;width:calc(100% - 30px);color:var(--ink);background:var(--white)}dialog::backdrop{background:#142b24aa}dialog h2{margin:16px 0}dialog li{margin:12px 0;font-size:14px}.dialog-close{float:right;border:0;background:#edf0e5;border-radius:50%;width:32px;height:32px;font-size:24px;line-height:1}.loading{padding:40px;text-align:center;color:var(--muted)}.inline-actions{display:flex;gap:10px;justify-content:center;flex-wrap:wrap}.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0)}@media(hover:hover){button:not(:disabled):hover{filter:brightness(.97)}.option:not(:disabled):hover{border-color:var(--green)}}@media(max-width:1000px){.hero{gap:35px;grid-template-columns:1fr 1fr}.header-note{display:none}.room-layout{grid-template-columns:minmax(0,1fr) 285px}.question{font-size:26px}}@media(max-width:760px){header,main,footer{padding-left:22px;padding-right:22px}header{height:85px}.brand{font-size:24px}.brand-icon{width:36px;height:36px;font-size:26px}.brand-dot{display:none}.connection{font-size:10px;padding:7px 9px}main{padding-top:32px}.hero{grid-template-columns:1fr;gap:30px}h1{font-size:59px;letter-spacing:-3.5px}.lead{font-size:16px}.sample{display:none}.card{padding:24px}.steps{grid-template-columns:1fr;margin-top:32px;gap:21px}.room-layout{grid-template-columns:1fr}.room-top{align-items:start}.room-top h1{font-size:31px;letter-spacing:-1px}.room-actions{flex-wrap:wrap;justify-content:end;max-width:150px}.code-pill{font-size:17px;padding:10px 12px;letter-spacing:2px}.room-actions .secondary{font-size:11px;padding:8px}.team-grid{gap:10px}.team-card{padding:16px}.team-card h3{font-size:17px}.members{min-height:76px}.game-stage{padding:23px}.question{font-size:26px;min-height:0}.options{grid-template-columns:1fr}.option{min-height:60px;padding:13px}.option.selected{padding:12px}.scoreboard{gap:0}.score-row{padding:9px 0}.results h1{font-size:39px;letter-spacing:-2px}footer{font-size:11px;gap:20px}.progress{margin:18px 0}.question-top{flex-wrap:wrap}.timer{width:51px;height:51px}.settings{order:2}dialog{padding:25px}.card-title h2{font-size:29px}}\n@media(prefers-reduced-motion:reduce){*{transition:none!important}}\n","type":"text/css; charset=utf-8"},"app.js":{"body":"'use strict';\nconst app=document.querySelector('#app');\nconst topicNames={math:'Математика',russian:'Русский язык',literature:'Литература',history:'История',geography:'География',science:'Естествознание'};\nconst topicIcons={math:'＋',russian:'Аа',literature:'▤',history:'⌛',geography:'◎',science:'✳'};\nconst colours=['#d7ef8a','#cbdfff','#ffd3b4','#e7d4fa'];\nconst API=(window.PEREMENA_API||location.origin).replace(/\\/$/,'');\nconst esc=v=>String(v??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\nlet saved;try{saved=JSON.parse(sessionStorage.getItem('peremena-session')||'null')}catch{}\nlet state=null,session=saved,mode=new URLSearchParams(location.search).has('room')?'join':'create',answerDraft='',busy=false,signature='',stamp=0,toastTimer,offset=0,lastRound=null;\nfunction toast(msg){const el=document.querySelector('#toast');el.textContent=msg;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),4200)}\nfunction connection(ok){const el=document.querySelector('#connection');el.textContent=ok?'● На связи':'○ Восстанавливаем связь';el.style.color=ok?'':'#9d5830'}\nfunction persist(){try{sessionStorage.setItem('peremena-session',JSON.stringify(session))}catch{toast('Браузер не разрешил сохранить вход. Не обновляйте вкладку.')}}\nfunction accept(s){if(s.serverTime<stamp)return;stamp=s.serverTime;offset=s.serverTime-Date.now();if(lastRound!==s.roundId){answerDraft='';lastRound=s.roundId}state=s;render()}\nasync function request(action,body={}){\n const controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),15000);\n try{const r=await fetch(API+'/api/'+action,{method:'POST',headers:{'Content-Type':'application/json',...(session?{Authorization:'Bearer '+session.token}:{})},body:JSON.stringify({code:session?.code,...body}),signal:controller.signal});const data=await r.json();if(!r.ok){const e=new Error(data.error||'Не удалось выполнить действие');e.status=r.status;throw e}connection(true);return data;}catch(e){if(e.name==='AbortError'||e instanceof TypeError){connection(false);throw new Error('Сервер пока не отвечает. Проверьте интернет и попробуйте ещё раз.')}throw e}finally{clearTimeout(timeout)}\n}\nasync function action(kind,data={}){if(busy)return;busy=true;document.querySelectorAll('[data-mutates],button[type=\"submit\"]').forEach(el=>el.disabled=true);try{const r=await request(kind,data);if(r.state)accept(r.state);return r}catch(e){toast(e.message);if(e.status===401||e.status===404){session=null;state=null;persist();signature='';render()}return null}finally{busy=false;signature='';render(true)}}\nfunction home(){return `<section class=\"hero\"><div><span class=\"eyebrow\"><i class=\"eyebrow-dot\"></i> КОМАНДНАЯ ВИКТОРИНА ДЛЯ СВОИХ</span><h1>Уроки кончились.<br><em>Игра начинается.</em></h1><p class=\"lead\">Соберите друзей, разделитесь на команды и вспомните то, что проходили в школе. Никаких оценок — только очки.</p><div class=\"hero-tags\"><span class=\"tag\">6 предметов</span><span class=\"tag\">120 вопросов</span><span class=\"tag\">2–4 команды</span><span class=\"tag\">С телефона и компьютера</span></div><div class=\"sample\"><div class=\"sample-symbol\">✳</div><div><strong>«Это же было в пятом классе!»</strong><p class=\"muted\">Знакомые вопросы. Неожиданные споры.</p></div></div></div><section class=\"card join-card\"><div class=\"card-title\"><h2>Собираемся?</h2><span class=\"small-star\" aria-hidden=\"true\">↗</span></div><p class=\"muted\">Для хорошей игры нужны только друзья.</p><div class=\"tabs\" role=\"tablist\" aria-label=\"Вход в игру\"><button class=\"tab ${mode==='create'?'active':''}\" role=\"tab\" aria-selected=\"${mode==='create'}\" data-action=\"mode\" data-mode=\"create\">Создать комнату</button><button class=\"tab ${mode==='join'?'active':''}\" role=\"tab\" aria-selected=\"${mode==='join'}\" data-action=\"mode\" data-mode=\"join\">Войти по коду</button></div><form id=\"entry\"><label class=\"field\">Как вас зовут?<input name=\"name\" placeholder=\"Например, Амир\" maxlength=\"20\" required autocomplete=\"nickname\" value=\"${esc(localStorageName())}\"></label>${mode==='join'?`<label class=\"field\">Код комнаты<input class=\"code\" name=\"code\" placeholder=\"ABC234\" maxlength=\"6\" minlength=\"6\" required autocomplete=\"off\" autocapitalize=\"characters\" value=\"${esc(new URLSearchParams(location.search).get('room')||'')}\"></label>`:''}<button type=\"submit\" class=\"primary full\" ${busy?'disabled':''}>${busy?'Подключаемся…':mode==='create'?'Создать комнату':'Присоединиться'} <span aria-hidden=\"true\">→</span></button></form><p class=\"hint\">Без регистрации. До 32 игроков в комнате.</p></section></section><section class=\"steps\"><div class=\"step\"><span class=\"step-num\">01</span><div><strong>Соберите компанию</strong><p>Отправьте друзьям код или ссылку на комнату.</p></div></div><div class=\"step\"><span class=\"step-num\">02</span><div><strong>Выберите свою команду</strong><p>Один вопрос для всех. Пишите ответ быстрее соперников.</p></div></div><div class=\"step\"><span class=\"step-num\">03</span><div><strong>Заберите победу</strong><p>100 очков тому, кто первым ответит правильно.</p></div></div></section>`}\nfunction localStorageName(){try{return localStorage.getItem('peremena-name')||''}catch{return ''}}\nconst me=()=>state.players.find(p=>p.id===state.me);\nconst isHost=()=>state.host===state.me;\nfunction top(title,subtitle){return `<div class=\"room-top\"><div><span class=\"eyebrow\">${state.phase==='lobby'?'ДО ЗВОНКА ОСТАЛОСЬ СОБРАТЬСЯ':'ПЕРЕМЕНА В РАЗГАРЕ'}</span><h1>${title}</h1><p class=\"muted\">${subtitle}</p></div><div class=\"room-actions\"><button class=\"code-pill\" data-action=\"copyCode\" aria-label=\"Скопировать код комнаты ${state.code}\">${state.code}</button><button class=\"secondary\" data-action=\"copyLink\">Ссылка ↗</button><button class=\"text-button\" data-action=\"leave\">Выйти</button></div></div>`}\nfunction lobby(){const s=state;const p=me();const host=isHost();const unassigned=s.players.filter(p=>p.team===null);return top('Все на перемену.',`${s.players.length} ${s.players.length===1?'игрок':'игроков'} в комнате · Вы здесь как ${esc(p.name)}${host?' · Вы ведущий':''}`)+`<div class=\"room-layout\"><section><div class=\"card\"><h3>За кого играете?</h3><p class=\"muted\">Выбирайте команду сами. Друзья могут присоединиться к вам.</p><div class=\"team-grid\">${s.teams.map((t,i)=>{const members=s.players.filter(p=>p.team===i);return `<section class=\"team-card\" style=\"--tc:${colours[i]}\"><div class=\"team-band\"></div><div class=\"team-title\"><h3>${esc(t)}</h3><span class=\"count\">${members.length} чел.</span></div><div class=\"members\">${members.length?members.map(m=>`<span class=\"member ${m.online?'':'offline'}\">${esc(m.name)}${m.id===s.host?' ♔':''}${m.id===s.me?' · вы':''}</span>`).join(''):'<span class=\"muted\">Пока никого</span>'}</div><button class=\"team-button ${p.team===i?'mine':''}\" data-action=\"team\" data-team=\"${i}\" data-mutates ${busy?'disabled':''}>${p.team===i?'✓ Ваша команда':'Выбрать команду →'}</button>${host?`<form class=\"rename\" data-team=\"${i}\"><input name=\"name\" maxlength=\"20\" required value=\"${esc(t)}\" aria-label=\"Название команды ${i+1}\"><button type=\"submit\" aria-label=\"Сохранить название команды\">✓</button></form>`:''}</section>`}).join('')}</div>${unassigned.length?`<p class=\"waiting\">Ещё выбирают: ${unassigned.map(p=>esc(p.name)).join(', ')}</p>`:'<p class=\"waiting\">✓ Все выбрали команду. Можно начинать!</p>'}</div></section><aside class=\"card settings\"><h3>${host?'Настроим игру':'Что будем играть'}</h3><p class=\"muted\">${host?'Выберите темп и любимые предметы.':'Ведущий настроит и запустит игру.'}</p>${host?`<form id=\"settings\" class=\"settings\"><div class=\"settings-grid\"><label class=\"field\">Вопросов<select name=\"rounds\">${[6,12,18,24].map(n=>`<option ${s.settings.rounds===n?'selected':''}>${n}</option>`).join('')}</select></label><label class=\"field\">Секунд<select name=\"seconds\">${[20,30,45].map(n=>`<option ${s.settings.seconds===n?'selected':''}>${n}</option>`).join('')}</select></label></div><label class=\"field\">Команд<select name=\"teamCount\">${[2,3,4].map(n=>`<option ${s.settings.teamCount===n?'selected':''}>${n}</option>`).join('')}</select></label><div><span class=\"field\">Предметы</span><div class=\"topic-checks\">${Object.entries(topicNames).map(([id,name])=>`<label><input type=\"checkbox\" name=\"topic\" value=\"${id}\" ${s.settings.topics.includes(id)?'checked':''}>${name}</label>`).join('')}</div></div><button type=\"submit\" class=\"secondary\">Сохранить настройки</button></form><button class=\"primary full\" data-action=\"start\" data-mutates ${busy?'disabled':''}>Начать игру <span>→</span></button>`:`<p>${s.settings.rounds} вопросов · ${s.settings.seconds} секунд<br>${s.settings.teamCount} команды</p><div class=\"hero-tags\">${s.settings.topics.map(t=>`<span class=\"tag\">${topicNames[t]}</span>`).join('')}</div><p class=\"answer-note\">Ждём, когда ведущий запустит игру.</p>`}<div class=\"rule-mini\"><strong>100 очков</strong> за правильный ответ.<br>Одна попытка на команду. Первый правильный ответ завершает раунд.</div></aside></div>`}\nfunction scores(){const s=state;return `<aside class=\"card scoreboard\"><span class=\"eyebrow\">ТАБЛО</span><h3>Командный зачёт</h3>${s.teams.map((t,i)=>{const a=s.answers[i];return `<div class=\"score-row\" style=\"--tc:${colours[i]}\"><div class=\"score-head\"><span><i class=\"team-dot\"></i>${esc(t)}${me().team===i?' · вы':''}</span><strong>${s.scores[i]}</strong></div><div class=\"status-sub\">${s.phase==='question'?(a?'Ответ отправлен':'Пишут ответ…'):a?(a.correct?'+100 · Верно':'0 · Неверно'):'0 · Нет ответа'}</div>${a?`<small>Ответил(а): ${esc(a.by)}</small>`:''}</div>`}).join('')}<p class=\"rule-mini\">Вопрос одинаковый для всех. Кто первым напишет правильный ответ, тот заберёт 100 очков.</p></aside>`}\nfunction game(){const s=state;const p=me();const answered=!!s.answers[p.team];const revealed=s.phase==='reveal';const own=s.answers[p.team];return top(`Вопрос ${s.round} из ${s.total}`,`${esc(p.name)} · ${p.team===null?'Без команды':esc(s.teams[p.team])}`)+`<div class=\"room-layout\"><section class=\"game-stage\"><div class=\"question-top\"><span class=\"tag\">${topicIcons[s.question.topic]} ${topicNames[s.question.topic]}</span><span class=\"round-label\">${revealed?'РАУНД ЗАКОНЧЕН':'КТО ОТВЕТИТ ПЕРВЫМ?'}</span><span id=\"timer\" class=\"timer\"></span></div><div class=\"progress\"><i id=\"timebar\"></i></div><h2 class=\"question\">${esc(s.question.text)}</h2>${revealed?`<div class=\"answer-note\"><strong>${s.winner!==null?esc(s.teams[s.winner])+' ответили первыми! +100 очков':'В этом раунде никто не ответил правильно.'}</strong><br>Правильный ответ: <strong>${esc(s.question.answer)}</strong>${own?'<br>Ваш ответ: '+esc(own.text):''}<br><span class=\"muted\">${s.round===s.total?'Итоги игры':'Следующий вопрос'} через <span id=\"nextTimer\"></span> сек.</span></div>${isHost()?`<button class=\"secondary\" style=\"margin-top:14px\" data-action=\"next\" data-mutates>Продолжить →</button>`:''}`:answered?`<div class=\"answer-note\">Ответ отправлен. Ждём итогов раунда.<br><span class=\"muted\">Ответил(а): ${esc(own.by)}</span></div>`:`<form id=\"answerForm\" style=\"margin-top:28px\"><label class=\"field\">Ваш ответ<input id=\"answerInput\" name=\"answer\" placeholder=\"Напишите ответ…\" maxlength=\"100\" required autocomplete=\"off\" value=\"${esc(answerDraft)}\" ${busy?'disabled':''}></label><button type=\"submit\" class=\"primary full\" ${busy?'disabled':''}>Ответить <span>→</span></button></form><p class=\"hint\">Одна попытка на команду. Первый правильный ответ забирает раунд.</p>`}</section>${scores()}</div>`}\nfunction finished(){const s=state;const teams=s.teams.map((name,i)=>({name,score:s.scores[i],i})).filter(t=>s.activeTeams.includes(t.i));const sorted=teams.sort((a,b)=>b.score-a.score);const winners=sorted.filter(t=>t.score===sorted[0]?.score);return top('Финальный звонок.',`Комната ${s.code} · Сыграно ${s.total} вопросов`)+`<section class=\"results\"><div class=\"trophy\" aria-hidden=\"true\">✳</div><span class=\"eyebrow\">${winners.length>1?'НИЧЬЯ — ДРУЖБА ПОБЕДИЛА':'ПОБЕДИТЕЛИ ЭТОЙ ПЕРЕМЕНЫ'}</span><h1>${winners.map(t=>esc(t.name)).join(' + ')}</h1><p class=\"muted\">${winners.length>1?'Равный счёт. Отличный повод для реванша.':'Кажется, кое-кто не зря ходил в школу.'}</p><div class=\"podium\">${sorted.map((t,i)=>`<div class=\"podium-row ${t.score===sorted[0].score?'winner':''}\"><span><span class=\"rank\">${i+1}</span>${esc(t.name)}</span><strong>${t.score}<small style=\"font-size:13px\"> очков</small></strong></div>`).join('')}</div>${isHost()?'<button class=\"primary\" data-action=\"replay\" data-mutates>Ещё одну перемену ↗</button>':'<p class=\"answer-note\">Ведущий может начать новую партию в этой комнате.</p>'}</section>`}\nfunction render(force=false){const sig=JSON.stringify({s:state&&{...state,serverTime:0,players:state.players.map(({online,...p})=>({...p,online}))},mode,busy,answerDraft});if(!force&&signature===sig){updateTimers();return}const focus=document.activeElement;if(!force&&focus?.matches('input,select')&&state?.phase==='lobby'&&signature){updateTimers();return}const keepAnswerFocus=focus?.id==='answerInput';signature=sig;app.innerHTML=state?(state.phase==='lobby'?lobby():state.phase==='finished'?finished():game()):home();if(keepAnswerFocus){const input=document.querySelector('#answerInput');if(input){input.focus();input.setSelectionRange(input.value.length,input.value.length)}}updateTimers()}\nfunction updateTimers(){if(!state)return;const time=Date.now()+offset;const remaining=Math.max(0,Math.ceil(((state.phase==='reveal'?state.nextAt:state.deadline)-time)/1000));const t=document.querySelector('#timer');if(t){t.textContent=state.phase==='reveal'?'✓':remaining;t.classList.toggle('urgent',state.phase==='question'&&remaining<=5)}const bar=document.querySelector('#timebar');if(bar)bar.style.width=(state.phase==='reveal'?100:Math.min(100,remaining/state.settings.seconds*100))+'%';const next=document.querySelector('#nextTimer');if(next)next.textContent=remaining}\nasync function copy(text){try{await navigator.clipboard.writeText(text);toast('Скопировано!')}catch{toast('Не удалось скопировать. Код комнаты: '+state.code)}}\ndocument.addEventListener('click',async e=>{const button=e.target.closest('[data-action]');if(!button||button.disabled)return;const kind=button.dataset.action;if(kind==='mode'){const n=document.querySelector('#entry input[name=name]')?.value;try{localStorage.setItem('peremena-name',n||'')}catch{}mode=button.dataset.mode;render(true)}else if(kind==='rules')document.querySelector('#rules').showModal();else if(kind==='closeRules')document.querySelector('#rules').close();else if(kind==='copyCode')copy(state.code);else if(kind==='copyLink'){const url=new URL(location.href);url.search='';url.hash='';url.searchParams.set('room',state.code);copy(url.href)}else if(kind==='team')await action('team',{team:Number(button.dataset.team)});else if(kind==='next')await action('next',{roundId:state.roundId});else if(kind==='leave'){const r=await action('leave');if(r){session=null;state=null;stamp=0;answerDraft='';persist();history.replaceState(null,'',location.pathname);render(true)}}else if(['start','replay'].includes(kind))await action(kind)});\ndocument.addEventListener('submit',async e=>{e.preventDefault();const f=e.target;const data=new FormData(f);if(f.id==='entry'){if(busy)return;busy=true;const button=f.querySelector('button[type=submit]');button.disabled=true;button.textContent='Подключаемся…';try{const r=await request(mode,{name:data.get('name'),code:data.get('code')});session={code:r.state.code,token:r.token};persist();try{localStorage.setItem('peremena-name',data.get('name'))}catch{}accept(r.state)}catch(err){toast(err.message)}finally{busy=false;signature='';render(true)}}else if(f.id==='answerForm'){await action('answer',{text:data.get('answer'),roundId:state.roundId})}else if(f.id==='settings'){await action('configure',{settings:{rounds:Number(data.get('rounds')),seconds:Number(data.get('seconds')),teamCount:Number(data.get('teamCount')),topics:data.getAll('topic')}})}else if(f.classList.contains('rename'))await action('rename',{team:Number(f.dataset.team),name:data.get('name')})});\nasync function poll(){try{if(session&&!busy){const r=await request('state');accept(r.state)}}catch(e){if(e.status===401||e.status===404){session=null;state=null;stamp=0;persist();render(true);toast(e.message)}else connection(false)}finally{setTimeout(poll,1100)}}\ndocument.addEventListener('input',e=>{if(e.target.id==='answerInput')answerDraft=e.target.value});\ndocument.addEventListener('visibilitychange',()=>{if(!document.hidden)updateTimers()});\nsetInterval(updateTimers,250);\nif(session){app.innerHTML='<div class=\"loading\">Возвращаемся в вашу комнату…</div>'}else render();poll();\n","type":"text/javascript; charset=utf-8"},"config.js":{"body":"window.PEREMENA_API = 'https://quiz-rooms-production-e463.up.railway.app';\n","type":"text/javascript; charset=utf-8"}};
const mount=Bun.env.RAILWAY_VOLUME_MOUNT_PATH;
const db=new Database(mount?mount+'/rooms.sqlite':':memory:');
db.exec('PRAGMA journal_mode=WAL;');
const handle=createTransport(createGame(db,QUESTIONS,TOPICS),assets,Bun.env.PUBLIC_ORIGIN);
Bun.serve({port:Number(Bun.env.PORT)||3000,hostname:'0.0.0.0',maxRequestBodySize:8192,fetch(request,server){return handle(request,server.requestIP(request)?.address||'unknown')}});
